// TypeScript bindings generated by ts-rs.
//
//   node scripts/bindings.mjs clean   remove target/ts-bindings (before `cargo test` regenerates it)
//   node scripts/bindings.mjs sync    copy target/ts-bindings -> src/api/generated (used by `npm run gen:types`)
//   node scripts/bindings.mjs verify  fail if src/api/generated differs from what Rust generates
//
// `cargo test` writes the bindings into target/ts-bindings (see .cargo/config.toml).
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, copyFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const generatedDir = process.env.SEXTANT_BINDINGS_OUT ?? join(root, "target", "ts-bindings");
const committedDir = process.env.SEXTANT_BINDINGS_COMMITTED ?? join(root, "src", "api", "generated");

function listFiles(dir) {
  if (!existsSync(dir)) return [];
  const out = [];
  const walk = (d) => {
    for (const name of readdirSync(d)) {
      const p = join(d, name);
      if (statSync(p).isDirectory()) walk(p);
      else out.push(relative(dir, p).split("\\").join("/"));
    }
  };
  walk(dir);
  return out.sort();
}

function clean() {
  rmSync(generatedDir, { recursive: true, force: true });
}

function sync() {
  const files = listFiles(generatedDir);
  if (files.length === 0) {
    console.error(`no bindings in ${generatedDir}; run cargo test first`);
    process.exit(1);
  }
  rmSync(committedDir, { recursive: true, force: true });
  for (const f of files) {
    mkdirSync(dirname(join(committedDir, f)), { recursive: true });
    copyFileSync(join(generatedDir, f), join(committedDir, f));
  }
  console.log(`synced ${files.length} binding files into ${relative(root, committedDir)}`);
}

function verify() {
  const generated = listFiles(generatedDir);
  const committed = listFiles(committedDir);
  if (generated.length === 0) {
    console.error(`no bindings in ${generatedDir}; run cargo test first`);
    process.exit(1);
  }
  const problems = [];
  for (const f of generated) {
    if (!committed.includes(f)) problems.push(`missing: ${f}`);
    else if (!readFileSync(join(generatedDir, f)).equals(readFileSync(join(committedDir, f)))) {
      problems.push(`differs: ${f}`);
    }
  }
  for (const f of committed) {
    if (!generated.includes(f)) problems.push(`stale: ${f}`);
  }
  if (problems.length > 0) {
    console.error("src/api/generated is out of date with the Rust types:");
    for (const p of problems) console.error(`  ${p}`);
    console.error("run: npm run gen:types");
    process.exit(1);
  }
  console.log(`bindings up to date (${generated.length} files)`);
}

const command = process.argv[2];
if (command === "clean") clean();
else if (command === "sync") sync();
else if (command === "verify") verify();
else {
  console.error("usage: node scripts/bindings.mjs clean|sync|verify");
  process.exit(2);
}
